MEANS = {"baseline": {"0.5": {"1": 0.010357, "2": 0.007695, "3": 0.005843, "4": 0.00322, "5": 0.001973, "6": 0.001261, "7": 0.00041}, "1": {"1": 0.018336, "2": 0.013714, "3": 0.010629, "4": 0.006, "5": 0.00377, "6": 0.00238, "7": 0.000759}, "2": {"1": 0.031776, "2": 0.02367, "3": 0.01868, "4": 0.010726, "5": 0.006702, "6": 0.004302, "7": 0.001382}, "3": {"1": 0.046335, "2": 0.034251, "3": 0.026134, "4": 0.015094, "5": 0.009431, "6": 0.006086, "7": 0.001953}}, "sandengine": {"0.5": {"1": 0.008944, "2": 0.006892, "3": 0.005141, "4": 0.002836, "5": 0.001769, "6": 0.001121, "7": 0.000367}, "1": {"1": 0.016096, "2": 0.012472, "3": 0.009569, "4": 0.005427, "5": 0.00347, "6": 0.002181, "7": 0.0007}, "2": {"1": 0.028164, "2": 0.021737, "3": 0.017013, "4": 0.009826, "5": 0.006227, "6": 0.003985, "7": 0.001291}, "3": {"1": 0.041415, "2": 0.031742, "3": 0.024053, "4": 0.013955, "5": 0.008841, "6": 0.005681, "7": 0.00183}}, "seagrass": {"0.5": {"1": 0.007407, "2": 0.005479, "3": 0.004033, "4": 0.002231, "5": 0.001404, "6": 0.000918, "7": 0.000318}, "1": {"1": 0.013129, "2": 0.009871, "3": 0.007391, "4": 0.004261, "5": 0.002776, "6": 0.001803, "7": 0.00062}, "2": {"1": 0.023312, "2": 0.017676, "3": 0.013663, "4": 0.008109, "5": 0.005221, "6": 0.003471, "7": 0.001163}, "3": {"1": 0.035299, "2": 0.02639, "3": 0.019744, "4": 0.011694, "5": 0.007501, "6": 0.005002, "7": 0.001656}}, "hybrid": {"0.5": {"1": 0.006447, "2": 0.004945, "3": 0.00359, "4": 0.001989, "5": 0.001266, "6": 0.00083, "7": 0.000293}, "1": {"1": 0.011558, "2": 0.009055, "3": 0.00674, "4": 0.003908, "5": 0.002584, "6": 0.001678, "7": 0.000587}, "2": {"1": 0.020701, "2": 0.016437, "3": 0.012684, "4": 0.007549, "5": 0.004925, "6": 0.003269, "7": 0.001112}, "3": {"1": 0.03144, "2": 0.024578, "3": 0.018328, "4": 0.01091, "5": 0.007068, "6": 0.004709, "7": 0.001563}}}

SCENARIO_NAMES = {
    "baseline": "Baseline (No Intervention)",
    "sandengine": "Sand Engine",
    "seagrass": "Seagrass Only",
    "hybrid": "Hybrid (Sand Engine + Seagrass)"
}

SCENARIO_COLORS = {
    "baseline": "#1f77b4",
    "sandengine": "#ff7f0e",
    "seagrass": "#9467bd",
    "hybrid": "#2ca02c"
}

# Create tabs
tab1, tab2, tab3, tab4 = st.tabs(["📊 Scenario Comparison", "📍 Spatial Overview", "📈 Mean Analysis", "🤖 Prediction Models"])

# TAB 1: Scenario Comparison
with tab1:
    st.subheader("Compare Wave Attenuation Across Scenarios")
    
    col1, col2 = st.columns(2)
    with col1:
        wave_height = st.selectbox("Wave Height", ["0.5", "1", "2", "3"], index=1, key="comp_wave")
    with col2:
        station = st.selectbox("River Station", ["1", "2", "3", "4", "5", "6", "7"], index=6, key="comp_station")
    
    scenarios_selected = st.multiselect(
        "Select Scenarios",
        ["baseline", "sandengine", "seagrass", "hybrid"],
        default=["baseline", "sandengine", "seagrass", "hybrid"],
        format_func=lambda x: SCENARIO_NAMES[x]
    )
    
    fig = go.Figure()
    base_mean = None
    hybrid_mean = None
    
    for sc in scenarios_selected:
        if wave_height in DATA[sc] and station in DATA[sc][wave_height]:
            y_data = DATA[sc][wave_height][station]
            fig.add_trace(go.Scatter(
                x=TIMESTAMPS,
                y=y_data,
                name=SCENARIO_NAMES[sc],
                line=dict(color=SCENARIO_COLORS[sc], width=2)
            ))
            if sc == "baseline":
                base_mean = np.mean(y_data)
            if sc == "hybrid":
                hybrid_mean = np.mean(y_data)
    
    fig.update_layout(
        title=f"Wave Height at River {station} ({wave_height}m Boundary Waves)",
        xaxis_title="Time",
        yaxis_title="Significant Wave Height (m)",
        hovermode="x unified",
        legend=dict(orientation="h", yanchor="bottom", y=1.02),
        height=450
    )
    st.plotly_chart(fig, use_container_width=True)
    
    if base_mean and hybrid_mean and base_mean > 0:
        reduction = ((base_mean - hybrid_mean) / base_mean * 100)
        st.info(f"📊 **Hybrid NbS Reduction:** {reduction:.1f}% average wave height reduction at River {station}")

# TAB 2: Spatial Overview
with tab2:
    st.subheader("Spatial Wave Attenuation Along River")
    
    col1, col2 = st.columns(2)
    with col1:
        spatial_wave = st.selectbox("Wave Height", ["0.5", "1", "2", "3"], index=1, key="spatial_wave")
    with col2:
        spatial_scenario = st.selectbox("Scenario", list(SCENARIO_NAMES.keys()), index=3, 
                                        format_func=lambda x: SCENARIO_NAMES[x], key="spatial_sc")
    
    colors = ["#440154", "#482878", "#3e4989", "#31688e", "#26828e", "#1f9e89", "#35b779"]
    fig = go.Figure()
    
    for i, r in enumerate(["1", "2", "3", "4", "5", "6", "7"]):
        if spatial_wave in DATA[spatial_scenario] and r in DATA[spatial_scenario][spatial_wave]:
            fig.add_trace(go.Scatter(
                x=TIMESTAMPS,
                y=DATA[spatial_scenario][spatial_wave][r],
                name=f"River {r}",
                line=dict(color=colors[i], width=2)
            ))
    
    fig.update_layout(
        title=f"Spatial Attenuation: {SCENARIO_NAMES[spatial_scenario]} ({spatial_wave}m Waves)",
        xaxis_title="Time",
        yaxis_title="Significant Wave Height (m)",
        hovermode="x unified",
        legend=dict(orientation="h", yanchor="bottom", y=1.02),
        height=450
    )
    st.plotly_chart(fig, use_container_width=True)
    
    st.info("📍 **Spatial Attenuation:** Wave energy decreases from River 1 (mouth) to River 7 (inland). The hybrid NbS shows the strongest attenuation effect.")

# TAB 3: Mean Analysis
with tab3:
    st.subheader("Mean Wave Height Analysis")
    
    mean_wave = st.selectbox("Wave Height", ["0.5", "1", "2", "3"], index=1, key="mean_wave")
    
    rivers = ["1", "2", "3", "4", "5", "6", "7"]
    
    # Calculate means
    base_means = [MEANS["baseline"][mean_wave][r] for r in rivers]
    se_means = [MEANS["sandengine"][mean_wave][r] for r in rivers]
    sg_means = [MEANS["seagrass"][mean_wave][r] for r in rivers]
    hybrid_means = [MEANS["hybrid"][mean_wave][r] for r in rivers]
    
    avg_base = np.mean(base_means)
    avg_hybrid = np.mean(hybrid_means)
    overall_reduction = ((avg_base - avg_hybrid) / avg_base * 100)
    
    # Stats cards
    col1, col2, col3, col4 = st.columns(4)
    with col1:
        st.metric("Baseline Mean", f"{avg_base*1000:.2f} mm")
    with col2:
        st.metric("Sand Engine", f"{np.mean(se_means)*1000:.2f} mm")
    with col3:
        st.metric("Seagrass", f"{np.mean(sg_means)*1000:.2f} mm")
    with col4:
        st.metric("Hybrid NbS", f"{avg_hybrid*1000:.2f} mm", f"-{overall_reduction:.1f}%")
    
    # Bar chart
    fig = go.Figure()
    fig.add_trace(go.Bar(x=[f"R{r}" for r in rivers], y=[v*1000 for v in base_means], name="Baseline", marker_color="#1f77b4"))
    fig.add_trace(go.Bar(x=[f"R{r}" for r in rivers], y=[v*1000 for v in se_means], name="Sand Engine", marker_color="#ff7f0e"))
    fig.add_trace(go.Bar(x=[f"R{r}" for r in rivers], y=[v*1000 for v in sg_means], name="Seagrass", marker_color="#9467bd"))
    fig.add_trace(go.Bar(x=[f"R{r}" for r in rivers], y=[v*1000 for v in hybrid_means], name="Hybrid", marker_color="#2ca02c"))
    
    fig.update_layout(
        title=f"Mean Wave Height by Station ({mean_wave}m Waves)",
        barmode="group",
        yaxis_title="Mean Wave Height (mm)",
        legend=dict(orientation="h", yanchor="bottom", y=1.02),
        height=400
    )
    st.plotly_chart(fig, use_container_width=True)
    
    # Reduction table
    st.subheader("Reduction Percentages")
    table_data = []
    for i, r in enumerate(rivers):
        se_red = ((base_means[i] - se_means[i]) / base_means[i] * 100) if base_means[i] > 0 else 0
        sg_red = ((base_means[i] - sg_means[i]) / base_means[i] * 100) if base_means[i] > 0 else 0
        hybrid_red = ((base_means[i] - hybrid_means[i]) / base_means[i] * 100) if base_means[i] > 0 else 0
        table_data.append({
            "Station": f"River {r}",
            "Baseline (mm)": f"{base_means[i]*1000:.3f}",
            "Sand Engine (mm)": f"{se_means[i]*1000:.3f}",
            "Seagrass (mm)": f"{sg_means[i]*1000:.3f}",
            "Hybrid (mm)": f"{hybrid_means[i]*1000:.3f}",
            "SE %": f"{se_red:.1f}%",
            "SG %": f"{sg_red:.1f}%",
            "Hybrid %": f"{hybrid_red:.1f}%"
        })
    st.dataframe(pd.DataFrame(table_data), use_container_width=True, hide_index=True)

# TAB 4: Prediction Models
with tab4:
    st.subheader("ML Surrogate Model Performance")
    
    col1, col2 = st.columns(2)
    
    with col1:
        st.markdown("### 🔵 SVR (Support Vector Regression)")
        st.markdown("**Wave Height Prediction**")
        st.metric("R² Score", "0.9927", help="Excellent predictive performance")
        st.metric("RMSE", "0.0142 m")
        st.markdown("**Sediment Transport Prediction**")
        st.metric("R² Score", "0.9099", help="Strong predictive performance")
        st.metric("RMSE", "0.0521 kg/m/s")
    
    with col2:
        st.markdown("### 🟢 GPR (Gaussian Process Regression)")
        st.markdown("**Wave Height Prediction**")
        st.metric("R² Score", "0.9924", help="Excellent predictive performance")
        st.metric("RMSE", "0.0156 m")
        st.markdown("**Sediment Transport Prediction**")
        st.metric("R² Score", "0.5322", delta="-0.3777 vs SVR", delta_color="inverse", help="Lower performance for sediment")
        st.metric("RMSE", "0.1847 kg/m/s")
    
    # Model comparison chart
    fig = go.Figure()
    fig.add_trace(go.Bar(x=["Wave R²", "Sediment R²"], y=[0.9927, 0.9099], name="SVR", marker_color="#1f77b4"))
    fig.add_trace(go.Bar(x=["Wave R²", "Sediment R²"], y=[0.9924, 0.5322], name="GPR", marker_color="#2ca02c"))
    fig.add_hline(y=0.85, line_dash="dash", line_color="red", annotation_text="Good fit threshold")
    
    fig.update_layout(
        title="Model Performance Comparison",
        barmode="group",
        yaxis=dict(range=[0, 1]),
        legend=dict(orientation="h", yanchor="bottom", y=1.02),
        height=400
    )
    st.plotly_chart(fig, use_container_width=True)
    
    st.info("🔬 **Key Finding:** SVR outperforms GPR for sediment transport prediction (R²=0.91 vs 0.53). Both achieve excellent wave height prediction (R²>0.99).")

